'use strict';
/* Cliente do Simulador de Empréstimo: interface que consome a API REST (/api). */

const $ = (id) => document.getElementById(id);
const moeda = (v) => Number(v).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
let token = sessionStorage.getItem('token');

function setState(s) {
  $('state').textContent = s;
}

async function chamarApi(metodo, caminho, corpo) {
  const resp = await fetch(caminho, {
    method: metodo,
    headers: { 'Content-Type': 'application/json', ...(token ? { Authorization: `Bearer ${token}` } : {}) },
    body: corpo ? JSON.stringify(corpo) : undefined,
  });
  const texto = await resp.text();
  const dados = texto ? JSON.parse(texto) : null;
  if (resp.status === 401 && caminho !== '/api/login') {
    encerrarSessaoLocal();
    $('loginMsg').innerHTML = '<span class="bad">Sessão inválida ou expirada. Faça login novamente.</span>';
  }
  return { status: resp.status, dados };
}

function mostrarApp() {
  $('login').classList.add('hidden');
  $('app').classList.remove('hidden');
  setState('Autenticado');
  carregarHistorico();
}

function encerrarSessaoLocal() {
  token = null;
  sessionStorage.removeItem('token');
  $('app').classList.add('hidden');
  $('login').classList.remove('hidden');
  $('result').classList.add('hidden');
  setState('Não autenticado');
}

async function login(evento) {
  evento.preventDefault();
  const r = await chamarApi('POST', '/api/login', { usuario: $('user').value, senha: $('pass').value });
  if (r.status === 200) {
    token = r.dados.token;
    sessionStorage.setItem('token', token);
    $('loginMsg').textContent = '';
    $('pass').value = '';
    mostrarApp();
  } else {
    $('loginMsg').innerHTML = '<span class="bad">Login ou senha inválidos.</span>';
  }
}

async function simulate(evento) {
  evento.preventDefault();
  const result = $('result');
  const r = await chamarApi('POST', '/api/simulacoes', {
    idade: $('age').value,
    renda: $('income').value,
    valor: $('amount').value,
    conta: $('active').value,
  });
  if (r.status === 401) return;
  result.classList.remove('hidden');
  if (r.status === 400) {
    result.innerHTML = '<span class="bad">Dados inválidos.</span>';
    return;
  }
  setState('Em Simulação');
  if (r.dados.resultado === 'APROVADO') {
    result.innerHTML = '<span class="ok">EMPRÉSTIMO APROVADO</span><br>Proposta gerada com sucesso.';
  } else {
    result.innerHTML = '<span class="bad">EMPRÉSTIMO NEGADO</span><br>Requisitos não atendidos.';
  }
  carregarHistorico();
}

function finish() {
  setState('Finalizado');
  $('result').classList.remove('hidden');
  $('result').innerHTML = '<strong>Simulação finalizada.</strong>';
}

async function sair() {
  await chamarApi('POST', '/api/logout');
  encerrarSessaoLocal();
}

async function carregarHistorico() {
  const r = await chamarApi('GET', '/api/simulacoes');
  if (r.status !== 200) return;
  const corpo = $('historico');
  corpo.innerHTML = '';
  r.dados.forEach((s) => {
    const tr = document.createElement('tr');
    tr.dataset.id = s.id;
    const celulas = [s.id, s.idade, moeda(s.renda), moeda(s.valor), s.conta === 'sim' ? 'Ativa' : 'Inativa', s.resultado];
    celulas.forEach((c) => {
      const td = document.createElement('td');
      td.textContent = c;
      tr.appendChild(td);
    });
    const tdAcao = document.createElement('td');
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.textContent = 'Excluir';
    btn.className = 'btnExcluir';
    btn.addEventListener('click', () => excluir(s.id));
    tdAcao.appendChild(btn);
    tr.appendChild(tdAcao);
    corpo.appendChild(tr);
  });
  $('historicoVazio').classList.toggle('hidden', r.dados.length > 0);
}

async function excluir(id) {
  const r = await chamarApi('DELETE', `/api/simulacoes/${id}`);
  if (r.status === 204) carregarHistorico();
}

$('formLogin').addEventListener('submit', login);
$('formSimulacao').addEventListener('submit', simulate);
$('btnFinalizar').addEventListener('click', finish);
$('btnSair').addEventListener('click', sair);

if (token) mostrarApp();

'use strict';
/**
 * Autenticação no servidor. Credenciais FICTÍCIAS de teste (admin / 1234),
 * configuráveis por variáveis de ambiente APP_USUARIO e APP_SENHA.
 */
const crypto = require('node:crypto');

function criarAutenticacao({ usuario, senha }) {
  const sessoes = new Map();

  return {
    login(u, s) {
      if (u !== usuario || s !== senha) return null;
      const token = crypto.randomBytes(24).toString('hex');
      sessoes.set(token, { usuario: u, criadaEm: Date.now() });
      return token;
    },
    validar(token) {
      return Boolean(token) && sessoes.has(token);
    },
    logout(token) {
      return sessoes.delete(token);
    },
  };
}

module.exports = { criarAutenticacao };

'use strict';
/**
 * Regras de negócio do Simulador de Empréstimo.
 * Portadas da versão 1.0 (v1.0/index.html, função simulate) sem alteração de comportamento.
 */

function validarEntrada(dados) {
  const idade = Number(dados.idade);
  const renda = Number(dados.renda);
  const valor = Number(dados.valor);
  if (!Number.isFinite(idade) || !Number.isFinite(renda) || !Number.isFinite(valor) ||
      idade < 0 || renda < 0 || valor <= 0) {
    return { valido: false };
  }
  return { valido: true, idade, renda, valor };
}

function idadeValida(idade) {
  return idade > 18 && idade < 60;
}

function rendaSuficiente(renda, valor) {
  return renda >= valor * 5;
}

function contaAtiva(conta) {
  return conta === 'sim';
}

function avaliarEmprestimo(dados) {
  const entrada = validarEntrada(dados);
  if (!entrada.valido) {
    return { resultado: 'DADOS_INVALIDOS' };
  }
  const aprovado = idadeValida(entrada.idade) &&
    rendaSuficiente(entrada.renda, entrada.valor) &&
    contaAtiva(dados.conta);
  return { resultado: aprovado ? 'APROVADO' : 'NEGADO' };
}

module.exports = { validarEntrada, idadeValida, rendaSuficiente, contaAtiva, avaliarEmprestimo };

'use strict';
/**
 * Persistência das simulações em arquivo JSON.
 * Escrita atômica (arquivo temporário + rename) para não corromper os dados.
 */
const fs = require('node:fs');
const path = require('node:path');

function criarRepositorio(arquivo) {
  function ler() {
    if (!fs.existsSync(arquivo)) return { proximoId: 1, simulacoes: [] };
    return JSON.parse(fs.readFileSync(arquivo, 'utf8'));
  }

  function gravar(dados) {
    fs.mkdirSync(path.dirname(arquivo), { recursive: true });
    const tmp = `${arquivo}.tmp`;
    fs.writeFileSync(tmp, JSON.stringify(dados, null, 2));
    fs.renameSync(tmp, arquivo);
  }

  return {
    listar() {
      return ler().simulacoes;
    },
    adicionar(simulacao) {
      const dados = ler();
      const registro = { id: dados.proximoId, ...simulacao, criadoEm: new Date().toISOString() };
      dados.proximoId += 1;
      dados.simulacoes.push(registro);
      gravar(dados);
      return registro;
    },
    remover(id) {
      const dados = ler();
      const antes = dados.simulacoes.length;
      dados.simulacoes = dados.simulacoes.filter((s) => s.id !== id);
      if (dados.simulacoes.length === antes) return false;
      gravar(dados);
      return true;
    },
    limpar() {
      gravar({ proximoId: 1, simulacoes: [] });
    },
  };
}

module.exports = { criarRepositorio };

'use strict';
/**
 * Servidor HTTP do Simulador de Empréstimo (sem dependências externas).
 *  - Arquivos estáticos da interface em /public
 *  - API REST em /api
 */
const http = require('node:http');
const fs = require('node:fs');
const path = require('node:path');
const { avaliarEmprestimo } = require('./regras');
const { criarRepositorio } = require('./repositorio');
const { criarAutenticacao } = require('./auth');

const TIPOS = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.css': 'text/css; charset=utf-8' };

function responderJson(res, status, corpo) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  res.end(corpo === undefined ? '' : JSON.stringify(corpo));
}

function lerCorpo(req) {
  return new Promise((resolve, reject) => {
    let bruto = '';
    req.on('data', (parte) => {
      bruto += parte;
      if (bruto.length > 1e5) reject(new Error('corpo muito grande'));
    });
    req.on('end', () => {
      if (!bruto) return resolve({});
      try { resolve(JSON.parse(bruto)); } catch { reject(new Error('JSON inválido')); }
    });
  });
}

function criarServidor(opcoes = {}) {
  const arquivoDados = opcoes.arquivoDados || process.env.DATA_FILE || path.join(__dirname, '..', 'data', 'simulacoes.json');
  const pastaPublica = path.join(__dirname, '..', 'public');
  const repo = criarRepositorio(arquivoDados);
  const auth = criarAutenticacao({
    usuario: opcoes.usuario || process.env.APP_USUARIO || 'admin',
    senha: opcoes.senha || process.env.APP_SENHA || '1234',
  });

  function tokenDe(req) {
    const cab = req.headers.authorization || '';
    return cab.startsWith('Bearer ') ? cab.slice(7) : null;
  }

  async function api(req, res, url) {
    const rota = `${req.method} ${url.pathname}`;

    if (rota === 'GET /api/saude') return responderJson(res, 200, { status: 'ok' });

    if (rota === 'POST /api/login') {
      const { usuario, senha } = await lerCorpo(req);
      const token = auth.login(usuario, senha);
      if (!token) return responderJson(res, 401, { erro: 'Login ou senha inválidos.' });
      return responderJson(res, 200, { token, usuario });
    }

    const token = tokenDe(req);
    if (!auth.validar(token)) return responderJson(res, 401, { erro: 'Sessão inválida ou expirada.' });

    if (rota === 'POST /api/logout') {
      auth.logout(token);
      return responderJson(res, 204);
    }

    if (rota === 'GET /api/simulacoes') return responderJson(res, 200, repo.listar());

    if (rota === 'POST /api/simulacoes') {
      const dados = await lerCorpo(req);
      const avaliacao = avaliarEmprestimo(dados);
      if (avaliacao.resultado === 'DADOS_INVALIDOS') {
        return responderJson(res, 400, { erro: 'Dados inválidos.' });
      }
      const registro = repo.adicionar({
        idade: Number(dados.idade),
        renda: Number(dados.renda),
        valor: Number(dados.valor),
        conta: dados.conta,
        ...avaliacao,
      });
      return responderJson(res, 201, registro);
    }

    const exclusao = url.pathname.match(/^\/api\/simulacoes\/(\d+)$/);
    if (req.method === 'DELETE' && exclusao) {
      const removido = repo.remover(Number(exclusao[1]));
      return removido ? responderJson(res, 204) : responderJson(res, 404, { erro: 'Simulação não encontrada.' });
    }

    return responderJson(res, 404, { erro: 'Rota não encontrada.' });
  }

  function estatico(req, res, url) {
    const relativo = url.pathname === '/' ? 'index.html' : url.pathname.slice(1);
    const arquivo = path.normalize(path.join(pastaPublica, relativo));
    if (!arquivo.startsWith(pastaPublica) || !fs.existsSync(arquivo) || fs.statSync(arquivo).isDirectory()) {
      res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
      return res.end('Não encontrado');
    }
    res.writeHead(200, { 'Content-Type': TIPOS[path.extname(arquivo)] || 'application/octet-stream' });
    fs.createReadStream(arquivo).pipe(res);
  }

  const servidor = http.createServer(async (req, res) => {
    const url = new URL(req.url, 'http://localhost');
    try {
      if (url.pathname.startsWith('/api/')) return await api(req, res, url);
      return estatico(req, res, url);
    } catch (erro) {
      return responderJson(res, 400, { erro: erro.message });
    }
  });
  servidor.repositorio = repo;
  return servidor;
}

if (require.main === module) {
  const porta = Number(process.env.PORT) || 3000;
  criarServidor().listen(porta, () => {
    console.log(`Simulador de Empréstimo em http://localhost:${porta}`);
  });
}

module.exports = { criarServidor };
